), comparacion AS (
 SELECT e.*,o.id AS orden_id,i.id AS item_id,i.cantidad_pedida,
        i.admin_eliminado_en
 FROM esperado e
 LEFT JOIN public.ordenes_produccion o ON o.numero_op=e.op
 LEFT JOIN public.items_orden i ON i.orden_id=o.id AND i.codigo=e.codigo AND i.talla=e.talla
), resumen AS (
 SELECT op,orden_id,count(*) AS lineas_excel,sum(cantidad) AS cantidad_excel,
        count(item_id) AS lineas_coincidentes_bd,
        count(*) FILTER(WHERE item_id IS NULL) AS lineas_faltantes,
        count(*) FILTER(WHERE item_id IS NOT NULL AND cantidad_pedida IS DISTINCT FROM cantidad) AS cantidades_diferentes,
        count(*) FILTER(WHERE admin_eliminado_en IS NOT NULL) AS lineas_eliminadas
 FROM comparacion GROUP BY op,orden_id
)
SELECT r.*,coalesce(b.lineas_bd,0) AS total_lineas_op_bd,
       coalesce(b.cantidad_bd,0) AS cantidad_op_bd,
       coalesce(b.lineas_bd,0)-r.lineas_coincidentes_bd AS lineas_adicionales_bd,
       CASE WHEN r.orden_id IS NULL THEN 'OP NO EXISTE'
            WHEN coalesce(b.lineas_bd,0)=0 THEN 'OP EXISTE SIN TALLAS'
            WHEN r.lineas_eliminadas>0 THEN 'REVISAR LINEAS ELIMINADAS'
            WHEN r.lineas_faltantes>0 THEN 'FALTAN TALLAS'
            WHEN r.cantidades_diferentes>0 THEN 'CANTIDADES DIFERENTES'
            WHEN b.lineas_bd>r.lineas_coincidentes_bd THEN 'HAY LINEAS ADICIONALES'
            ELSE 'COINCIDE CON V2' END AS diagnostico
FROM resumen r
LEFT JOIN LATERAL (
 SELECT count(*) AS lineas_bd,sum(cantidad_pedida) AS cantidad_bd
 FROM public.items_orden WHERE orden_id=r.orden_id
) b ON true
ORDER BY CASE WHEN r.op='26241' THEN 0 ELSE 1 END,r.op;
